#' Unit tests for sparseGenSetCal.
#'
#' The tests that matter most are the cross-language ones: the R package is a
#' port of the Python reference implementation, so it has to reproduce the same
#' numbers on the same matrix rather than merely produce plausible ones.  The
#' fixtures for those live in tests/testthat/fixtures/ and are generated by
#' tests/testthat/make_fixtures.py.

fixture <- function(name) {
    path <- test_path("fixtures", name)
    if (!file.exists(path)) {
        skip(paste("fixture", name, "not present"))
    }
    path
}

small <- function(n_cells = 300, n_genes = 900, seed = 11) {
    make_synthetic_matrix(n_cells = n_cells, n_genes = n_genes, seed = seed)
}

# ----------------------------------------------------------------------
# the closed form
# ----------------------------------------------------------------------
test_that("tau falls as cells get deeper and is zero at the ceiling", {
    tau <- tie_break_level(c(100, 200, 400, 800, 1000), 1000, 20000)
    expect_true(all(diff(tau) < 0))
    expect_equal(tau[5], 0)
})

test_that("tie-break inclusion is the fraction of unused slots", {
    # 400 detected of 20,000, ceiling 1,000: 600 slots out of 19,600 genes.
    expect_equal(tie_break_inclusion(400, 1000, 20000), 600 / 19600)
    expect_equal(tie_break_inclusion(1000, 1000, 20000), 0)
    expect_equal(tie_break_inclusion(1200, 1000, 20000), 0)
})

test_that("tie_break_share is zero for an always-detected set and rises as it sparsifies", {
    depth <- rep(400, 500)
    expect_equal(tie_break_share(rep(1, 30), depth, 1000, 20000), 0)
    shares <- vapply(c(0.5, 0.1, 0.01), function(p) {
        tie_break_share(rep(p, 30), depth, 1000, 20000)
    }, numeric(1))
    expect_true(all(diff(shares) > 0))
    expect_gt(shares[3], 0.7)
})

test_that("counts are not multiplied as integers", {
    # sum() on a logical returns an integer, so a product of two margins
    # overflows to NA for any table of more than 46,341 cells -- and silently,
    # since NA is what an undefined statistic looks like anyway.  These tables
    # are deliberately larger than that and deliberately unbalanced, so an
    # association is present and a zero would be a failure rather than a null.
    n <- 40000
    groups <- c(rep(FALSE, n), rep(TRUE, n))
    outcome <- c(rep(TRUE, 0.6 * n), rep(FALSE, 0.4 * n),
                 rep(TRUE, 0.4 * n), rep(FALSE, 0.6 * n))
    stat <- sparseGenSetCal:::chi2_split(outcome, groups)
    expect_true(is.finite(stat))
    expect_gt(stat, 0)
    # and the same guard on the AUC, whose denominator is a product of two
    # counts: 40000 x 40000 is past 2^31 twice over
    score <- as.numeric(groups) + seq_along(groups) / length(groups)
    expect_true(is.finite(auroc(score, outcome)))
})

test_that("a perfectly separating score returns 1 and does not fail", {
    # The other end of the range: a score that separates the outcome
    # completely.  It is a legitimate value rather than a degenerate one, so
    # the framework reports it instead of clipping at 0.99 or refusing the
    # comparison -- an analysis whose gene set does separate has to be able to
    # say so.
    score <- c(seq_len(50), -seq_len(50))
    outcome <- c(rep(TRUE, 50), rep(FALSE, 50))
    expect_equal(auroc(score, outcome), 1)
    expect_equal(auroc(-score, outcome), 0)
    expect_true(is.finite(auroc(score, outcome)))
    # Heavy ties across the classes fall back on the mid-rank convention and
    # stay inside the unit interval rather than drifting past it.
    tied <- c(rep(1, 10), rep(0, 10))
    outcome <- c(rep(TRUE, 5), rep(FALSE, 5), rep(TRUE, 5), rep(FALSE, 5))
    expect_equal(auroc(tied, outcome), 0.5)
})

test_that("the outcome-driven cutpoint is found on a realistically sized table", {
    # Regression: the best cutpoint used to come back NA once the sample passed
    # a few hundred cells per side, which reports as "no outcome-driven rule"
    # rather than as an error, and would have flattered the very rule the
    # package exists to criticise.
    set.seed(3)
    score <- stats::rnorm(2000)
    outcome <- score + stats::rnorm(2000) > 0
    cut <- optimum_cutpoint(score, outcome)
    expect_true(is.finite(cut))
    expect_true(cut > stats::quantile(score, 0.05) &&
                cut < stats::quantile(score, 0.95))
})

test_that("the decomposition reproduces aucell exactly", {
    X <- small()
    cache <- rank_cache(X$matrix, X$genes, ceiling = 40)
    gs <- X$genes[1:8]
    # The ceiling is given to both calls.  Left out, each falls back to its own
    # default of ceil(0.05 * G), which for 900 genes is 45 -- not the cache's 40
    # -- and the two halves of equation (2) are then computed over different
    # windows of the ranking and silently disagree.
    split <- score_decomposition(cache, gs, X$matrix > 0, max_rank = 40)
    expect_equal(split$total, aucell(cache, gs, max_rank = 40), tolerance = 1e-12)
    expect_true(all(split$tie_break >= 0))
    expect_true(all(split$detected >= 0))

    # The defaults agree with each other, which is the property that lets a
    # caller omit the argument from both.  They agree even when the cache's
    # ceiling is lower than the default, because both read the same truncated
    # cache: the agreement is between the two functions, not with the truth --
    # and aucell() warns that what it returns is then a lower bound.
    expect_gt(ceiling(0.05 * cache$n_genes_total), cache$ceiling)
    expect_warning(default_aucell <- aucell(cache, gs),
                   "above the cache ceiling")
    expect_equal(score_decomposition(cache, gs, X$matrix > 0)$total,
                 default_aucell, tolerance = 1e-12)
})

test_that("preflight needs no score and returns a verdict", {
    set.seed(1)
    depth <- round(exp(rnorm(500, log(450), 0.4)))
    axis <- rnorm(500)
    pf <- preflight(depth, axis, 1000, 20000)
    expect_true(pf$verdict %in% c("CLEAR", "CAUTION", "CONFOUNDED"))
    expect_true(is.finite(pf$chance_band))
    # tau is a deterministic function of depth, so the confound has to be
    # strongest against an axis that tracks depth.
    axis2 <- depth + rnorm(500)
    pf2 <- preflight(depth, axis2, 1000, 20000)
    expect_gt(abs(pf2$tau_axis_rho), abs(pf$tau_axis_rho))
})

# ----------------------------------------------------------------------
# the rank cache
# ----------------------------------------------------------------------
test_that("every cell's ranks are a permutation of 1..ceiling", {
    X <- small(n_cells = 60)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 20)
    # apply() would return a 20 x n_cells matrix here, so the assertion is made
    # per row rather than over the elements of that matrix.
    complete <- apply(cache$clipped, 1L, function(r) {
        identical(as.integer(sort(r[r > 0])), as.integer(seq_len(20)))
    })
    expect_true(all(complete))
})

test_that("the cache records each cell's depth over the whole panel", {
    X <- small(n_cells = 80)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 20)
    expect_equal(cache$depth, as.integer(Matrix::rowSums(X$matrix > 0)))
    expect_equal(cache$n_genes_total, ncol(X$matrix))
})

test_that("the cache is reproducible under one seed and not under another", {
    X <- small(n_cells = 60)
    a <- rank_cache(X$matrix, X$genes, ceiling = 20, seed = 1)
    b <- rank_cache(X$matrix, X$genes, ceiling = 20, seed = 1)
    c_ <- rank_cache(X$matrix, X$genes, ceiling = 20, seed = 2)
    expect_identical(a$clipped, b$clipped)
    expect_false(identical(a$clipped, c_$clipped))
})

test_that("a cache refuses a ceiling the matrix cannot support", {
    X <- small()
    expect_error(rank_cache(X$matrix, X$genes, ceiling = ncol(X$matrix)),
                 "ceiling must lie in")
})

# ----------------------------------------------------------------------
# matched nulls
# ----------------------------------------------------------------------
test_that("a matched null never reuses a gene of the set it replaces", {
    # This is a regression test.  Excluding only the gene being replaced leaves
    # the set's other members eligible; the drawn set then shares genes with the
    # observation, and every P value drawn from it is conservative.
    X <- small(n_cells = 300, n_genes = 900, seed = 21)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 40)
    builder <- MatchedNullBuilder$new(cache, det_floor = 0.005, seed = 5)
    gs <- cache$genes[seq_len(8)]
    sets <- builder$sample(gs, 20, kind = "expression")
    overlaps <- vapply(sets, function(s) length(intersect(s, gs)), integer(1))
    expect_equal(sum(overlaps), 0)
})

test_that("the drawn sets match the observed detection rate", {
    X <- small(n_cells = 300, n_genes = 900, seed = 22)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 40)
    # Genes of middling detection: the sparsest decile is censored by the
    # detection floor, which is what the next test covers.
    middle <- order(abs(cache$detection - stats::median(cache$detection)))
    gs <- cache$genes[middle][seq_len(10)]
    built <- construct_expression_matched_null(cache, gs, n_sets = 5, seed = 2)
    expect_lt(abs(built$detection_ratio - 1), 0.05)
    expect_equal(built$max_overlap, 0L)
    expect_equal(built$status, "PASS")
})

test_that("the null status does not depend on how many draws were asked for", {
    # The status is a property of the pool, not of the sample size.  Deciding
    # it on the largest gap over draws made it a function of n_sets instead: a
    # maximum can only grow as more draws are taken, so one pool would pass at
    # 25 draws and fail at 100.
    X <- small(n_cells = 400, n_genes = 1200, seed = 31)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 50)
    band <- which(cache$detection > 0.01 & cache$detection < 0.08)
    expect_gte(length(band), 12)
    gs <- cache$genes[band][seq_len(12)]

    statuses <- character(0)
    worsts <- numeric(0)
    means <- numeric(0)
    for (n in c(10, 50, 200)) {
        built <- construct_expression_matched_null(cache, gs, n_sets = n,
                                                   seed = 11)
        expect_equal(built$max_overlap, 0L)
        statuses <- c(statuses, built$status)
        worsts <- c(worsts, built$worst_detection_gap)
        means <- c(means, built$mean_detection_gap)
    }
    expect_length(unique(statuses), 1)
    # The maximum is monotone in the draw count -- which is the reason it
    # cannot decide the status -- while the mean settles down.
    expect_lte(worsts[1], worsts[3] + 1e-9)
    expect_lt(max(means) - min(means), 0.01)
    expect_true(all(worsts >= means))
})

test_that("a null that cannot avoid the set is reported as failing", {
    X <- small(n_cells = 300, n_genes = 900, seed = 23)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 40)
    builder <- MatchedNullBuilder$new(cache, det_floor = 1e-4, seed = 1)
    big <- cache$genes[order(cache$detection, decreasing = TRUE)][1:400]
    built <- construct_expression_matched_null(cache, big, n_sets = 3, seed = 1)
    expect_gt(built$max_overlap, 0)
    expect_equal(built$status, "FAIL")
})

test_that("the adaptive floor does not censor the sparsest sets", {
    X <- small(n_cells = 300, n_genes = 900, seed = 24)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 40)
    sparse <- cache$genes[order(cache$detection)][1:12]
    adaptive <- adaptive_detection_floor(cache, sparse, cap = 0.01)
    expect_lt(adaptive, 0.01)
    fixed <- construct_expression_matched_null(
        cache, sparse, n_sets = 4, seed = 3,
        tolerance = 0.05)
    expect_true(fixed$det_floor <= 0.01)
})

# ----------------------------------------------------------------------
# diagnostics and the checklist
# ----------------------------------------------------------------------
test_that("the sparsity report prefers the exact criterion when depth is known", {
    X <- small(n_cells = 250, n_genes = 800, seed = 31)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 40)
    rep <- sparsity_report(cache, cache$genes[1:10])
    expect_equal(rep$criterion, "tie_break_share")
    expect_true(rep$tie_break_share >= 0 && rep$tie_break_share <= 1)
    expect_true(rep$frac_above_floor >= 0 && rep$frac_above_floor <= 1)
})

test_that("the verdict says which criterion it used", {
    X <- small(n_cells = 250, n_genes = 800, seed = 32)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 40)
    v <- verdict(sparsity_report(cache, cache$genes[1:10]))
    expect_equal(v$criterion, "tie_break_share")
    expect_true(v$verdict %in% c("INTERPRETABLE",
                                 "INTERPRETABLE_WITH_MATCHED_NULL",
                                 "NOT_IDENTIFIABLE"))
})

test_that("a weak reason never lowers a severity a strong one has set", {
    # Every field that can raise the severity to HIGH, followed by every field
    # that would otherwise set it to MODERATE.  Comparing the three severities
    # as strings gets this wrong, because "MODERATE" sorts above "HIGH".
    high_share <- list(observed_zero_rate = 0.05, zero_rate_excess = 0.01,
                       tie_break_share = 0.9, frac_above_floor = 1,
                       detection_floor = 0.005)
    high_zero <- list(observed_zero_rate = 0.75, zero_rate_excess = 0.01,
                      tie_break_share = 0.01, frac_above_floor = 1,
                      detection_floor = 0.005)
    for (rep in list(high_share, high_zero)) {
        for (extra in list(list(), list(used_matched_null = FALSE),
                           list(outcome_driven_cutpoint = TRUE),
                           list(externally_replicated = FALSE))) {
            args <- c(list(report = rep), extra)
            v <- do.call(verdict, args)
            expect_equal(v$severity, "HIGH", info = paste(names(extra), collapse = ","))
            expect_equal(v$verdict, "NOT_IDENTIFIABLE")
        }
    }
})

test_that("omitting the matched null cannot improve the verdict", {
    clean <- list(observed_zero_rate = 0.05, zero_rate_excess = 0.01,
                  tie_break_share = 0.01, frac_above_floor = 1,
                  detection_floor = 0.005)
    unmatched <- verdict(clean, used_matched_null = FALSE)
    matched <- verdict(clean, used_matched_null = TRUE)
    expect_equal(matched$verdict, "INTERPRETABLE")
    expect_equal(unmatched$verdict, "INTERPRETABLE_WITH_MATCHED_NULL")
    expect_true(match(unmatched$severity, SEVERITY_ORDER) >=
                match(matched$severity, SEVERITY_ORDER))
})

test_that("the checklist runs end to end and serialises", {
    X <- small(n_cells = 250, n_genes = 800, seed = 33)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 40)
    set.seed(9)
    axis <- rnorm(nrow(X$matrix))
    out <- diagnostic_checklist(cache, cache$genes[1:10], axis = axis,
                                cutpoint_method = "median",
                                config = list(n_null = 10,
                                              cutpoint_permutations = 25),
                                label = "demo")
    expect_equal(out$label, "demo")
    for (step in c("step1_sparsity", "step2_null_construction",
                   "step3_false_positive_rate", "step4_external_replication")) {
        expect_true(!is.null(out[[step]]), info = step)
    }
    expect_true(out$overall_verdict %in% c("INTERPRETABLE",
                                           "INTERPRETABLE_WITH_MATCHED_NULL",
                                           "NOT_IDENTIFIABLE"))
    expect_equal(out$step1_sparsity$criterion, "tie_break_share")

    path <- tempfile(fileext = ".json")
    to_json(out, path)
    back <- jsonlite::fromJSON(path, simplifyVector = FALSE)
    expect_equal(back$overall_verdict, out$overall_verdict)
})

test_that("collection fields serialise as arrays whatever their length", {
    # The Python implementation writes them as arrays, so a length-one reason
    # has to arrive as ["..."] rather than "..." or the two objects are not
    # interchangeable once parsed.  The field is written by hand here because
    # the point is the shape, not the values.
    for (reason in list("one reason", c("first", "second", "third"),
                        character(0))) {
        path <- tempfile(fileext = ".json")
        to_json(list(overall_verdict = "NOT_IDENTIFIABLE", reasons = reason,
                     step1_sparsity = list(status = "PASS"),
                     step4_external_replication = list(success = NULL)),
                path)
        txt <- paste(readLines(path), collapse = " ")
        expect_match(txt, '"reasons" *: *\\[', info = length(reason))
        back <- jsonlite::fromJSON(path, simplifyVector = FALSE)
        expect_length(back$reasons, length(reason))
        expect_true(is.list(back$reasons))
        # A null field is a value, not a collection, and stays null; deleting
        # one must not renumber the fields around it.
        expect_null(back$step4_external_replication$success)
        expect_equal(names(back$step4_external_replication), "success")
    }
    # A null inside a step record must not swallow the fields after it.
    path <- tempfile(fileext = ".json")
    to_json(list(step4 = list(attempted = TRUE, success = NULL, status = "PASS")),
            path)
    back <- jsonlite::fromJSON(path, simplifyVector = FALSE)
    expect_equal(names(back$step4), c("attempted", "success", "status"))
})

test_that("a one-gene null set is still an array of genes", {
    path <- tempfile(fileext = ".json")
    to_json(list(null_genes = list("CD8A", c("GZMB", "PRF1"))), path)
    back <- jsonlite::fromJSON(path, simplifyVector = FALSE)
    expect_length(back$null_genes, 2)
    expect_length(back$null_genes[[1]], 1)
    expect_equal(back$null_genes[[1]][[1]], "CD8A")
})

test_that("step 3 measures the rule and step 4 reports what it was told", {
    X <- small(n_cells = 250, n_genes = 800, seed = 34)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 40)
    set.seed(10)
    axis <- rnorm(nrow(X$matrix))
    out <- diagnostic_checklist(cache, cache$genes[1:10], axis = axis,
                                cutpoint_method = "optimum",
                                externally_replicated = FALSE,
                                config = list(n_null = 10,
                                              cutpoint_permutations = 25))
    expect_true(out$step3_false_positive_rate$attempted)
    expect_equal(out$step3_false_positive_rate$method, "optimum")
    expect_equal(out$step4_external_replication$status, "FAIL")
    # an outcome-chosen cutpoint is a high-severity finding on its own
    expect_equal(out$severity, "HIGH")
})

test_that("no axis means steps 3 and 4 are reported as not attempted", {
    X <- small(n_cells = 200, n_genes = 700, seed = 35)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 40)
    out <- diagnostic_checklist(cache, cache$genes[1:10],
                                config = list(n_null = 10))
    expect_false(out$step3_false_positive_rate$attempted)
    expect_equal(out$step4_external_replication$status, "NOT_ATTEMPTED")
})

test_that("an unknown configuration key is refused rather than ignored", {
    X <- small(n_cells = 150, n_genes = 600, seed = 36)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 40)
    expect_error(diagnostic_checklist(cache, cache$genes[1:8],
                                      config = list(not_a_key = 1)),
                 "unknown configuration keys")
})

# ----------------------------------------------------------------------
# the conventional tests
# ----------------------------------------------------------------------
test_that("the outcome-chosen cutpoint costs more false positives than the median", {
    set.seed(12)
    score <- rnorm(400)
    outcome <- score > 0            # unrelated to the score's ranking by cut
    med <- cutpoint_fpr(score, outcome, n_perm = 200, method = "median", seed = 1)
    opt <- cutpoint_fpr(score, outcome, n_perm = 200, method = "optimum", seed = 1)
    expect_lt(med$fpr, 0.15)
    expect_gt(opt$fpr, med$fpr)
})

test_that("the permutation test is calibrated on unrelated vectors", {
    set.seed(13)
    score <- rnorm(200)
    axis <- rnorm(200)
    out <- all_conventional(score, axis, n_perm = 200, seed = 2)
    expect_true(out$permutation_p >= 0 && out$permutation_p <= 1)
    expect_true(is.finite(out$naive_p))
})

test_that("the Monte-Carlo P value defaults to two-sided", {
    # The tail is the one argument a caller forgets, and a one-sided default
    # answers a narrower question than the caller asked.  It did: the matched
    # nulls were read in the lower tail while the conventional analyses they are
    # compared against reject in either direction, which halved every matched
    # rejection rate and reported the matched null's power as zero.
    nulls <- seq(-1, 1, length.out = 201)
    centre <- stats::median(nulls)
    expect_equal(empirical_p(nulls, 0.5),
                 empirical_p(nulls, 0.5, tail = "two-sided"))
    expect_equal(null_summary(nulls, 0.5)$p_value,
                 empirical_p(nulls, 0.5, tail = "two-sided"))

    # Definition: distance from the null's own centre, not from zero.
    for (observed in c(-0.9, -0.2, 0, 0.4, 1)) {
        k <- sum(abs(nulls - centre) >= abs(observed - centre))
        expect_equal(empirical_p(nulls, observed, tail = "two-sided"),
                     (k + 1) / (length(nulls) + 1))
    }

    # A centred null makes the two conventions agree, which is why folding the
    # values about zero looks harmless; an off-centre one -- what imperfect
    # matching produces -- makes them differ, and the folded version then
    # answers the naive question the matched null was drawn to replace.
    expect_equal(empirical_p(abs(nulls), 0.5, tail = "upper"),
                 empirical_p(nulls, 0.5, tail = "two-sided"))
    shifted <- nulls + 0.4
    expect_lt(empirical_p(abs(shifted), 0.9, tail = "upper"),
              empirical_p(shifted, 0.9, tail = "two-sided"))
})

test_that("a family that was not drawn has no verdict", {
    # `kinds` is a free parameter, and the headline verdicts follow it.  Asking
    # for the expression family alone used to report `passed_strictest = FALSE`
    # -- a failed co-detection test that was never run -- and asking for
    # co-detection without a detection matrix was downgraded to the same FALSE.
    # The Python port raises in the second case, so the two ports disagreed
    # about what had happened on the same input.
    X <- small(n_cells = 250, n_genes = 700, seed = 41)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 35)
    builder <- MatchedNullBuilder$new(cache, det_floor = 0.005, seed = 5)
    gs <- cache$genes[seq_len(8)]
    score <- aucell(cache, gs, max_rank = 35)
    axis <- score + seq(0, 1, length.out = length(score))

    partial <- tier2_internal(score, axis, builder, gs, 35, n_null = 8,
                              seed = 3, kinds = "expression")
    expect_equal(partial$passed_family, "expression")
    expect_true(is.logical(partial$passed))
    expect_true(is.na(partial$passed_strictest))
    expect_true(is.na(partial$passed_strictest_family))

    # Asked for and undrawable: refused in the words the Python port uses.
    expect_error(tier2_internal(score, axis, builder, gs, 35, n_null = 5,
                                seed = 3),
                 "needs detection_matrix")
})

# ----------------------------------------------------------------------
# cross-language equivalence
# ----------------------------------------------------------------------

read_fixture_matrix <- function(path) {
    lines <- readLines(path)
    header <- lines[1]
    n_cells <- as.integer(sub(".*n_cells=([0-9]+).*", "\\1", header))
    n_genes <- as.integer(sub(".*n_genes=([0-9]+).*", "\\1", header))
    # Lines 1 and 2 are the comment and the column names, so the text handed to
    # read.csv has no header of its own.
    triples <- utils::read.csv(text = paste(lines[-c(1, 2)], collapse = "\n"),
                               header = FALSE,
                               col.names = c("row", "col", "value"))
    X <- Matrix::sparseMatrix(i = triples$row + 1L, j = triples$col + 1L,
                              x = triples$value, dims = c(n_cells, n_genes),
                              repr = "C")
    list(matrix = X, genes = sprintf("G%05d", seq_len(n_genes) - 1L))
}

test_that("aucell reproduces the Python reference on the same matrix", {
    # A port has to reproduce the reference engine's numbers, not merely produce
    # numbers of the same kind.  The matrix and the Python scores are written by
    # tests/testthat/make_fixtures.py.
    ref <- readLines(fixture("aucell_reference.csv"))
    header <- ref[1]
    ceiling <- as.integer(sub(".*ceiling=([0-9]+).*", "\\1", header))
    max_rank <- as.integer(sub(".*max_rank=([0-9]+).*", "\\1", header))
    gene_set <- strsplit(sub(".*gene_set=([^ ]+).*", "\\1", header), ",")[[1]]
    expected <- utils::read.csv(text = paste(ref[-1], collapse = "\n"))

    dat <- read_fixture_matrix(fixture("matrix.csv"))
    cache <- rank_cache(dat$matrix, dat$genes, ceiling = ceiling, seed = 2024,
                        chunk = 100)
    got <- aucell(cache, gene_set, max_rank = max_rank)

    expect_equal(length(got), nrow(expected))
    # Exact to floating point: the tie-break seed and the ranking rule are the
    # same on both sides, so anything larger than rounding is a real difference.
    expect_lt(max(abs(got - expected$aucell)), 1e-9)
})

test_that("ucell reproduces the Python reference on the same matrix", {
    ref <- readLines(fixture("aucell_reference.csv"))
    ceiling <- as.integer(sub(".*ceiling=([0-9]+).*", "\\1", ref[1]))
    gene_set <- strsplit(sub(".*gene_set=([^ ]+).*", "\\1", ref[1]), ",")[[1]]
    expected <- utils::read.csv(text = paste(ref[-1], collapse = "\n"))
    r_max <- as.integer(round(median(Matrix::rowSums(
        read_fixture_matrix(fixture("matrix.csv"))$matrix > 0))))

    dat <- read_fixture_matrix(fixture("matrix.csv"))
    cache <- rank_cache(dat$matrix, dat$genes, ceiling = ceiling, seed = 2024,
                        chunk = 100)
    got <- ucell(cache, gene_set, r_max = min(r_max, ceiling))
    expect_lt(max(abs(got - expected$ucell)), 1e-9)
})

test_that("the diagnostics reproduce the Python reference", {
    ref <- utils::read.csv(fixture("diagnostics_reference.csv"))
    want <- stats::setNames(ref$value, ref$quantity)
    dat <- read_fixture_matrix(fixture("matrix.csv"))
    gene_set <- sprintf("G%05d", 0:11)
    cache <- rank_cache(dat$matrix, dat$genes, ceiling = 60, seed = 2024,
                        chunk = 100)
    rep <- sparsity_report(cache, gene_set)

    expect_equal(rep$observed_zero_rate, want[["observed_zero_rate"]],
                 tolerance = 1e-9)
    expect_equal(rep$structural_zero_rate, want[["structural_zero_rate"]],
                 tolerance = 1e-9)
    expect_equal(rep$mean_detection, want[["mean_detection"]], tolerance = 1e-9)
    expect_equal(rep$median_depth, want[["median_depth"]], tolerance = 1e-9)
    # The headline diagnostic, to six figures.
    expect_equal(rep$tie_break_share, want[["tie_break_share"]],
                 tolerance = 1e-8)
    expect_equal(rep$mean_inclusion, want[["mean_inclusion"]], tolerance = 1e-8)
})

test_that("comparability flags panels that place a set on different scales", {
    tab <- comparability_report(list(a = c(20000, 5000), b = c(24646, 4000)),
                                rank_frac = 0.05)
    expect_equal(nrow(tab), 2)
    expect_gt(attr(tab, "max_rank_ratio"), 1.2)
    expect_false(attr(tab, "scale_comparable"))
})

test_that("depth_report recommends an r_max from the data, not the default", {
    X <- small(n_cells = 200, n_genes = 800, seed = 41)
    dr <- depth_report(X$matrix)
    expect_equal(dr$n_genes_in_matrix, 800L)
    expect_gt(dr$ucell_r_max_implied, 0)
