# ----------------------------------------------------------------------
# the tie-break
# ----------------------------------------------------------------------
# These are the tests that would have failed against a generator-driven tie
# break, and they are the reason R/tiebreak.R exists: a draw from the stream
# depends on how the matrix was blocked and on which language is drawing, and
# neither dependence is acceptable in a port whose numbers are published.

test_that("the cache does not depend on how the work was blocked", {
    X <- small(n_cells = 120)
    a <- rank_cache(X$matrix, X$genes, ceiling = 25, seed = 3, chunk = 120)
    b <- rank_cache(X$matrix, X$genes, ceiling = 25, seed = 3, chunk = 37)
    c_ <- rank_cache(X$matrix, X$genes, ceiling = 25, seed = 3, chunk = 1)
    expect_identical(a$clipped, b$clipped)
    expect_identical(a$clipped, c_$clipped)
    # and the seed still changes the answer, so the equality above is not the
    # equality of a cache that ignores its seed
    d <- rank_cache(X$matrix, X$genes, ceiling = 25, seed = 4, chunk = 120)
    expect_false(identical(a$clipped, d$clipped))
})

test_that("a key is a function of the coordinates, not of their order", {
    whole <- sparseGenSetCal:::tie_break_keys(0:9, 50, seed = 7)
    band <- sparseGenSetCal:::tie_break_keys(2:4, 50, seed = 7)
    expect_equal(whole[3:5, ], band)
    expect_equal(dim(whole), c(10L, 50L))
    # in range, and spread over it rather than clustered
    expect_true(all(whole >= 0 & whole < 4294967296))
    expect_gt(length(unique(as.vector(whole))), 400)
})

test_that("an exact tie is settled by the key and not by the gene order", {
    # Two genes at the same count, and only room for one inside the ceiling.
    block <- matrix(c(5, 5, 0, 0), nrow = 1L)
    keys <- matrix(c(11, 2, 0, 0), nrow = 1L)
    expect_equal(sparseGenSetCal:::ranked_columns(block, keys, 1L)[1, 1], 2L)
    keys <- matrix(c(2, 11, 0, 0), nrow = 1L)
    expect_equal(sparseGenSetCal:::ranked_columns(block, keys, 1L)[1, 1], 1L)
})

test_that("an undetected gene never outranks a detected one", {
    # A count of one beats a zero whatever the keys say; this is the reason the
    # undetected fill lands beyond the ceiling in the first place.
    block <- matrix(c(1, 0, 1, 0), nrow = 2L, byrow = TRUE)
    keys <- matrix(c(4294967295, 0, 4294967295, 0), nrow = 2L, byrow = TRUE)
    expect_equal(sparseGenSetCal:::ranked_columns(block, keys, 1L)[, 1],
                 c(1L, 1L))
})

test_that("the tie-break keys reproduce the Python reference exactly", {
    # Not statistically similar: equal.  The keys are 32-bit integers computed
    # in 16-bit halves precisely so that both languages get the same ones.
    lines <- readLines(fixture("keys_reference.csv"))
    n_genes <- as.integer(sub(".*n_genes=([0-9]+).*", "\\1", lines[1]))
    seed <- as.integer(sub(".*seed=([0-9]+).*", "\\1", lines[1]))
    want <- utils::read.csv(text = paste(lines[-1], collapse = "\n"))
    cells <- sort(unique(want$cell))
    genes <- sort(unique(want$gene))
    K <- sparseGenSetCal:::tie_break_keys(cells, n_genes, seed = seed)
    got <- K[cbind(match(want$cell, cells), match(want$gene, genes))]
    expect_equal(got, as.numeric(want$key))
})

test_that("the ranking reproduces the Python reference cell by cell", {
    # The end-to-end check: not the hash on its own but the order it produced,
    # for every rank of every probed cell.
    lines <- readLines(fixture("ranks_reference.csv"))
    header <- lines[1]
    n_cells <- as.integer(sub(".*n_cells=([0-9]+).*", "\\1", header))
    n_genes <- as.integer(sub(".*n_genes=([0-9]+).*", "\\1", header))
    ceiling <- as.integer(sub(".*ceiling=([0-9]+).*", "\\1", header))
    seed <- as.integer(sub(".*seed=([0-9]+).*", "\\1", header))
    want <- utils::read.csv(text = paste(lines[-1], collapse = "\n"))

    dat <- read_fixture_matrix(fixture("matrix.csv"))
    # Deliberately a different chunk from the one Python used, so a difference
    # in blocking shows up as a failed test rather than as a lucky pass.
    cache <- rank_cache(dat$matrix, dat$genes, ceiling = ceiling, seed = seed,
                        chunk = 53)
    top <- sparseGenSetCal:::ranked_columns(
        as.matrix(dat$matrix),
        sparseGenSetCal:::tie_break_keys(seq_len(n_cells) - 1L, n_genes,
                                         seed = seed),
        ceiling)
    got <- top[cbind(match(want$cell, seq_len(n_cells) - 1L), want$rank)]
    expect_equal(got, want$gene + 1L)

    # and the same order read out of the package's own cache, so the test
    # covers rank_cache() and not only ranked_columns()
    for (cell in sort(unique(want$cell))) {
        row <- want[want$cell == cell, ]
        ranks <- cache$clipped[cell + 1L, ]
        hit <- which(ranks > 0)
        expect_equal(as.integer(ranks[hit][order(ranks[hit])]), sort(row$rank))
        expect_equal(hit[order(ranks[hit])], row$gene[order(row$rank)] + 1L)
    }
})

# ----------------------------------------------------------------------
# the edge cases the brief asks the framework to refuse or warn on
# ----------------------------------------------------------------------
# The framework's records arrive as `sparsegs_event` conditions, so they can be
# caught by class without silencing the caller's own warnings -- which is the
# reason the records are signalled rather than printed.
record_of <- function(expr) {
    tryCatch(expr, sparsegs_event = function(w) conditionMessage(w))
}

test_that("a score with no spread is refused", {
    # Edge case three: a set that is off in every cell, or on in every cell.
    # The correlation such a score enters is 0/0, and left alone it returns a
    # NaN that surfaces much later with nothing to say about which set produced
    # it -- so the refusal happens where the score is made, and names the set.
    check_score <- sparseGenSetCal:::check_score
    # The refusal is a record as well as an error, so a log of a failed run says
    # which set had no spread rather than only that some set did.
    seen <- character(0)
    quiet <- function(expr) withCallingHandlers(
        suppressWarnings(expr), message = function(m) {
            seen <<- c(seen, conditionMessage(m))
            invokeRestart("muffleMessage")
        })
    expect_error(quiet(check_score(rep(0.3, 50), label = "flat")),
                 "zero variance")
    # The advice the brief asks for is in the message, not only in the log: a
    # caller who catches the error is the one who has to act on it.
    expect_error(quiet(check_score(rep(0, 50), label = "all zero")),
                 "consider different genes")
    expect_length(seen, 2)
    expect_match(seen[1], "score_has_no_variance", fixed = TRUE)
    expect_match(seen[1], "label=flat", fixed = TRUE)
    # A label with a space in it is quoted, so the record parses back into the
    # fields it was built from.
    expect_match(seen[2], 'label="all zero"', fixed = TRUE)
    # A score with any real spread passes, and the check returns what it saw.
    expect_gt(check_score(seq(0, 1, length.out = 50)), MIN_SCORE_SD)
})

test_that("a perfect AUC warns with the three things to check", {
    # Edge case two: an AUC of 0.99 is a claim about the data, not the score.
    # It is warned about rather than refused, because a marker can genuinely
    # separate what it marks; the brief's three candidate explanations are
    # carried into the record so the warning can be acted on.
    check_auc <- sparseGenSetCal:::check_auc
    expect_silent(check_auc(0.5))
    record <- record_of(check_auc(0.999, label = "T-cell set"))
    expect_match(record, "suspicious_score_separation")
    expect_match(record, "T-cell set", fixed = TRUE)
    for (check in c("batch_effects", "outcome_leakage_into_cell_type_annotation",
                    "extreme_sparsity")) {
        expect_match(record, check, fixed = TRUE)
    }
    # The threshold travels with the record, so a reader of the log can tell how
    # far past it the value was without knowing this package's constants.
    expect_match(record, "threshold=0.99", fixed = TRUE)
    # A score that separates the two groups just as perfectly in the other
    # direction is the same confound, and auroc() does not fold its argument
    # about 0.5 -- so an upper-tail-only check would have missed half the ways
    # this case can arise.
    reversed <- record_of(check_auc(0.002, label = "T-cell set"))
    expect_match(reversed, "auc=0.002", fixed = TRUE)
    expect_match(reversed, "separation=0.998", fixed = TRUE)
})

test_that("a background too thin to draw from is refused not approximated", {
    # Edge case one, at the point the ladder gives up.  A query covering all but
    # a handful of the background leaves almost nothing to replace it with.  The
    # framework loosens the detection floor once, by the brief's ten per cent,
    # announces that it did, and -- if the pool is still too thin -- refuses.
    # Drawing from five genes and calling the result a matched null is the
    # failure this case exists to prevent.
    X <- small(n_cells = 200, n_genes = 600, seed = 41)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 30)
    query <- utils::head(cache$genes, length(cache$genes) - 5)
    seen <- character(0)
    err <- tryCatch(
        withCallingHandlers(
            construct_expression_matched_null(cache, query, n_sets = 1, seed = 1),
            sparsegs_event = function(w) {
                seen <<- c(seen, conditionMessage(w))
                invokeRestart("muffleWarning")
            }),
        error = function(e) conditionMessage(e))
    expect_match(err, "Cannot construct matched null", fixed = TRUE)
    expect_match(err, "Consider different gene set", fixed = TRUE)
    # The loosening is announced before the refusal, so a log of a failed call
    # records that the framework tried the brief's remedy rather than skipping
    # straight to the error.
    record <- paste(seen, collapse = "\n")
    expect_match(record, "background_insufficient", fixed = TRUE)
    expect_match(record, "loosening", fixed = TRUE)
    expect_match(record, "loosened_to=", fixed = TRUE)
})

test_that("a gene set that fits its background is not warned about", {
    # The guard above has to stay quiet when there is no problem: a warning that
    # fires on ordinary input is a warning that gets filtered out of the log,
    # which costs the warnings that matter.  The widening has to be visible in
    # the object as well as the log, because a reader of a calibration record
    # cannot tell a matched null from a widened one by looking at the P value it
    # produced.
    X <- small(n_cells = 200, n_genes = 600, seed = 42)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 30)
    query <- utils::head(cache$genes, max(20, length(cache$genes) %/% 10))
    seen <- character(0)
    built <- withCallingHandlers(
        construct_expression_matched_null(cache, query, n_sets = 1, seed = 1),
        sparsegs_event = function(w) {
            seen <<- c(seen, conditionMessage(w))
            invokeRestart("muffleWarning")
        })
    expect_length(seen, 0)
    expect_false(built$det_floor_loosened)
    expect_gt(built$n_available_background, MIN_BACKGROUND_GENES)
    expect_equal(built$pool_floor, built$det_floor)
})

test_that("the log is machine readable", {
    # Every field is `key=value`, so a log can be counted and not just read.
    # The point of emitting records rather than sentences is that the question
    # "how often did this happen" has an answer, and that answer requires the
    # format to hold.
    line <- record_of(sparseGenSetCal:::event(
        "warning", "test_event", count = 3, ratio = 0.125, ok = TRUE,
        name = "a value with spaces", absent = NULL))
    fields <- regmatches(
        line, gregexpr("(\\w+)=(\"[^\"]*\"|\\S+)", line))[[1]]
    got <- setNames(sub("^\\w+=", "", fields), sub("=.*$", "", fields))
    expect_equal(unname(got[["count"]]), "3")
    expect_equal(unname(got[["ratio"]]), "0.125")
    expect_equal(unname(got[["ok"]]), "true")
    expect_equal(unname(got[["name"]]), "\"a value with spaces\"")
    expect_false("absent" %in% names(got))
})

test_that("an unknown log level is refused rather than guessed at", {
    # A caller who asked for "warn" and was silently given "warning" cannot
    # tell the difference between a level that was accepted and one that was
    # guessed at.
    expect_error(set_log_level("warn"), "unknown log level")
    expect_equal(set_log_level("error"), "error")
    set_log_level("warning")
})

# ----------------------------------------------------------------------
# the axis's own confound with depth, folded into the verdict
# ----------------------------------------------------------------------
test_that("the axis confound qualifies a verdict without refusing it", {
    # A matched null is calibrated *under* this confound: the replacement sets
    # come from a matrix with the same depth distribution and carry the same
    # tie-break behaviour, so the null distribution moves with the observed
    # statistic and the confound is priced in.  Calling a depth-confounded axis
    # NOT_IDENTIFIABLE outright would say the framework's own recommended
    # analysis cannot be trusted on the data it was built for.
    clean <- list(observed_zero_rate = 0.05, zero_rate_excess = 0.01,
                  tie_break_share = 0.01, frac_above_floor = 1.0,
                  detection_floor = 0.005)

    clear <- verdict(clean, used_matched_null = TRUE,
                     preflight = list(verdict = "CLEAR"))
    expect_equal(clear$verdict, "INTERPRETABLE")
    expect_equal(clear$severity, "LOW")

    for (name in c("CAUTION", "CONFOUNDED")) {
        v <- verdict(clean, used_matched_null = TRUE,
                     preflight = list(verdict = name))
        expect_equal(v$verdict, "INTERPRETABLE", info = name)
        expect_equal(v$severity, "MODERATE", info = name)
        expect_true(any(grepl("sequencing depth", v$reasons)), info = name)
    }

    # Without a matched null the confound joins the reasons already there, and
    # the verdict is the one that says a matched null is owed.
    v <- verdict(clean, used_matched_null = FALSE,
                 preflight = list(verdict = "CONFOUNDED"))
    expect_equal(v$verdict, "INTERPRETABLE_WITH_MATCHED_NULL")
    expect_true(any(grepl("expression-matched null", v$reasons)))
    expect_true(any(grepl("sequencing depth", v$reasons)))

    # A verdict that already refuses is not softened by the extra reason: the
    # heavier severity still wins, which is what comparing the names as strings
    # gets wrong -- "MODERATE" sorts above "HIGH".
    v <- verdict(utils::modifyList(clean, list(observed_zero_rate = 0.7)),
                 used_matched_null = TRUE,
                 preflight = list(verdict = "CONFOUNDED"))
    expect_equal(v$verdict, "NOT_IDENTIFIABLE")
    expect_equal(v$severity, "HIGH")
})

test_that("the checklist reads the depth off the cache", {
    # The pre-flight has to run without being asked to.  The axis below is the
    # depth itself, so the correlation is -1 -- a positive test rather than a
    # borderline one, because the question is whether the number is computed at
    # all when no `depth` argument is passed.  The density is set so that the
    # median cell is comfortably below `max_rank`: `tau` is zero for every cell
    # at or above that ceiling, so a matrix deeper than it flattens the axis's
    # image into a constant and the correlation stops being near one.
    X <- make_synthetic_matrix(n_cells = 300, n_genes = 2000, density = 0.02,
                               seed = 51)
    cache <- rank_cache(X$matrix, X$genes, ceiling = 100)
    axis <- as.numeric(cache$depth)
    out <- diagnostic_checklist(cache, cache$genes[1:12], axis = axis,
                                used_matched_null = TRUE,
                                config = list(n_null = 3,
                                              cutpoint_permutations = 25))

    expect_false(is.null(out$preflight))
    expect_equal(out$preflight$verdict, "CONFOUNDED")
    expect_gt(abs(out$preflight$tau_axis_rho), 0.9)
    expect_true(any(grepl("sequencing depth", out$reasons)))
    # The band it judged against travels with the call, so a reader can see
    # which regime the dataset is in rather than taking the threshold on trust.
    expect_equal(out$preflight$chance_band, 1.96 / sqrt(out$n_cells - 3),
                 tolerance = 1e-12)

    # An axis that is not the depth is not warned about, so the reason above is
    # the correlation and not the fact that a pre-flight ran.
    set.seed(52)
    free <- diagnostic_checklist(cache, cache$genes[1:12],
                                 axis = rnorm(out$n_cells),
                                 used_matched_null = TRUE,
                                 config = list(n_null = 3,
                                               cutpoint_permutations = 25))
    expect_equal(free$preflight$verdict, "CLEAR")
    expect_false(any(grepl("sequencing depth", free$reasons)))
})

test_that("a tie-break that never varies is clear and says so", {
    # Every cell deeper than `max_rank` contributes tau = 0; on a matrix where
    # all of them are, tau is constant and its correlation with the axis does
    # not exist.  `cor.test` reports NA here with a warning about a zero
    # standard deviation, which `spearman` suppresses so that the degenerate
    # input is a number and not a diagnostic.  This is not an exotic input: it
    # is what a deep 10x matrix looks like whenever five per cent of the gene
    # panel falls below the median cell.
    depth <- rep(500, 300)
    axis <- seq(0, 1, length.out = 300)
    pre <- preflight(depth, axis, 100, 2000)
    expect_true(pre$tau_constant)
    expect_equal(pre$tau_sd, 0)
    expect_true(is.na(pre$tau_axis_rho))
    # Clear, and correctly so: a component that never varies cannot carry an
    # association with anything.
    expect_equal(pre$verdict, "CLEAR")

    # A matrix with depth variation still produces a correlation, so the branch
    # above is the degenerate case and not the ordinary one.
    live <- seq(20, 400, length.out = 300)
    expect_true(is.finite(preflight(live, axis, 100, 2000)$tau_axis_rho))
})
